const AC=AgentCore, AGENT_KEY='scholarion-agents-r103';
const metrics=['Unanswered agent questions','Empty help searches','Support requests','Late submissions','Locked content attempts','Waitlists','Registered without access','Failed or stuck jobs'];
function initialAgents(){const knowledge=[{id:'learning',pack:'Learning guide',keywords:['certificate','credentials','completion'],answer:'Scholarion certificate programs focus on structured learning and completion credentials.',approved:true},{id:'registration',pack:'Registration guide',keywords:['registration','enroll','access'],answer:'In this local preview, selected programs appear in My courses. A selection does not create a paid enrollment.',approved:true},{id:'support',pack:'Support guide',keywords:['help','support','password'],answer:'Use the demo workspace selector to enter the learner, faculty or administrator workspace. Live account recovery is not connected.',approved:true}];return {agents:['Help Desk','Registration Guide','AIM310 Study Partner'].map((name,i)=>{const d=AC.defaults(['Support','Registration','Teaching Assistant'][i]);d.name=name;d.scope=i===2?'course':'institution';return {id:'seed-'+i,draft:d,active:AC.activate(d,'admin')};}),knowledge,logs:[],signals:[],proposals:[]};}
let agentData;try{agentData=JSON.parse(localStorage.getItem(AGENT_KEY))||initialAgents();}catch{agentData=initialAgents();}
function saveAgents(){localStorage.setItem(AGENT_KEY,JSON.stringify(agentData));}
const canBuild=()=>['admin','faculty'].includes(model.role);
const ownAgent=a=>model.role==='admin'||(model.role==='faculty'&&a.draft.scope==='course'&&a.draft.course==='AIM310');
function signal(metric,count=1,opportunities=1,course='AIM310'){if(!metrics.includes(metric))return;agentData.signals.push({metric,count,opportunities,course,time:Date.now()});saveAgents();}
function totals(metric,course,since=0){return agentData.signals.filter(s=>s.metric===metric&&(!course||s.course===course)&&s.time>since).reduce((a,s)=>({count:a.count+s.count,opportunities:a.opportunities+s.opportunities}),{count:0,opportunities:0});}
let builder=null,step=0;
const agentButton=(text,action)=>`<button class="button secondary" data-agent="${action}">${text}</button>`;
function agentHome(){return heading('Agent workspace','Approved knowledge, fixed activated versions, and human oversight.',canBuild()?btn('Build an agent','#agent-builder'):'')+`<p class="feedback">Local demonstration · Rule-based retrieval · No live AI or background monitoring. Release 2026.10.3-r103.</p><div class="agent-grid">${agentData.agents.filter(a=>a.active&&(a.active.audience==='student'||canBuild())&& (model.role!=='faculty'||a.active.scope==='institution'||a.active.course==='AIM310')).map(a=>`<section class="card"><span class="badge">Active v${a.active.version}</span><h2>${esc(a.active.name)}</h2><p>${esc(a.active.role)} · ${esc(a.active.scope)}</p>${btn('Open agent','#agent/'+a.id)} ${canBuild()&&ownAgent(a)?btn('Edit draft','#agent-builder/'+a.id,true):''}</section>`).join('')}</div><h2>Governance tools</h2>${canBuild()?btn('Improvement proposals','#improvement',true)+btn('Knowledge review','#knowledge',true)+btn('Course insights','#course-insights',true):'<p>Staff review knowledge and proposals before changes reach learners.</p>'}<details class="card"><summary>Policy and privacy limits</summary><p>The original policy attachment was not available. Refusal wording and audit fields are provisional. Pattern checks are demonstrative and cannot replace server-side authorization or comprehensive PII protection.</p><p>Questions are processed in memory, common email/phone/name patterns are redacted, and only a SHA-256 fingerprint is retained. No question or answer text is stored in turn logs.</p></details>`;}
function builderPage(id){if(!canBuild())return heading('Staff workspace required','Choose a faculty or administrator demo workspace to build agents.',btn('Choose workspace','#signin'));const existing=agentData.agents.find(a=>a.id===id);if(existing&&!ownAgent(existing))return heading('Outside your course scope','Faculty may edit AIM310 agents only.');if(!builder||builder.id!==(id||'new')){builder={id:id||'new',draft:structuredClone(existing?.draft||AC.defaults('Teaching Assistant'))};step=0;}const d=builder.draft;const names=['Role','Basic info','Instructions','Packs','Skills','Done'];let content='';if(step===0)content=`<h2>Pick a role to start with</h2><div class="role-grid">${AC.roles.map((r,i)=>`<label class="role-choice ${d.role===r?'selected':''}"><input type="radio" name="agent-role" value="${r}" ${d.role===r?'checked':''}><span class="role-icon">${i+1}</span><strong>${r}</strong></label>`).join('')}</div>`;if(step===1)content=`<h2>Give your agent a purpose</h2><label>Name<input name="agent-name" value="${esc(d.name)}" required></label><label>Audience<select name="agent-audience"><option value="student" ${d.audience==='student'?'selected':''}>Student facing</option><option value="staff" ${d.audience==='staff'?'selected':''}>Staff drafts only</option></select></label><label>Scope<select name="agent-scope"><option value="course">My course · AIM310</option>${model.role==='admin'?`<option value="institution" ${d.scope==='institution'?'selected':''}>Institution wide</option>`:''}</select></label>`;if(step===2)content=`<h2>Instructions</h2><label>Agent instructions<textarea name="agent-instructions" rows="7">${esc(d.instructions)}</textarea></label><p>Approved sources only. No graded-work completion, unreleased content, grade changes or cross-institution access.</p>`;if(step===3||step===4){const key=step===3?'packs':'skills';content=`<h2>Choose ${key}</h2>${AC[key].map(x=>`<label class="agent-check"><input type="checkbox" data-config="${key}" value="${x}" ${d[key].includes(x)?'checked':''}>${x}${AC.staffSkills.includes(x)?' · Staff only':''}</label>`).join('')}`;}if(step===5)content=`<h2>Ready for review</h2><h3>${esc(d.name)}</h3><p>${esc(d.role)} · ${esc(d.audience)} · ${esc(d.scope)}</p><p>${esc(d.instructions)}</p><p>Packs: ${d.packs.map(esc).join(', ')}</p><p>Skills: ${d.skills.map(esc).join(', ')}</p><p>Activation creates a fixed version. Draft edits never change the active version.</p>${agentButton('Save draft','save')}${agentButton('Activate version','activate')}`;return heading('Agent Builder','A six-step launch pad. Start with a role, then shape its knowledge and abilities.')+`<ol class="agent-steps">${names.map((n,i)=>`<li ${i===step?'aria-current="step"':''}>${i+1} ${n}</li>`).join('')}</ol><section class="card builder">${content}<p id="agent-error" role="alert"></p><div class="agent-actions">${step?agentButton('Back','back'):''}${step<5?agentButton('Continue','next'):''}</div></section>`;}
function knowledgePage(){if(!canBuild())return heading('Knowledge library','Approved sources used by the demonstration agents.')+agentData.knowledge.filter(k=>k.approved).map(k=>`<article class="card" id="${k.id}"><h2>${esc(k.pack)}</h2><p>${esc(k.answer)}</p></article>`).join('');return heading('Knowledge review','Write and approve source material. Original unanswered questions are never retained.')+`<form id="knowledge-form" class="card"><label>Knowledge pack<select name="pack">${AC.packs.map(p=>`<option>${p}</option>`).join('')}</select></label><label>Search keywords, comma separated<input name="keywords" required></label><label>Reviewed answer<textarea name="answer" required rows="4"></textarea></label><p>${model.role==='faculty'?'This source is restricted to AIM310.':'Institution source. Use no personal information.'}</p><button class="button">Approve knowledge source</button></form>`+agentData.knowledge.filter(k=>model.role==='admin'||!k.course||k.course==='AIM310').map(k=>`<article class="card"><h2>${esc(k.pack)}</h2><p>${esc(k.answer)}</p><small>Approved source · ${esc(k.id)} ${k.course?'· '+k.course:''}</small></article>`).join('');}
function agentChat(id){const a=agentData.agents.find(a=>a.id===id);if(!a?.active||a.active.audience==='staff'&&!canBuild())return heading('Agent unavailable','No accessible active version.');return heading(a.active.name,`Active version ${a.active.version} · ${a.active.role}`)+`<section class="card"><p>Answers use reviewed sources only. Do not enter personal information.</p><form id="agent-chat" data-id="${a.id}"><label>Your question<input name="question" required maxlength="2000" autocomplete="off"></label><button class="button">Ask agent</button></form><div id="agent-answer" aria-live="polite"></div></section>`;}
function improvementPage(courseOnly=false){if(!canBuild())return heading('Staff workspace required','Improvement proposals require human review.');const course=model.role==='faculty'||courseOnly?'AIM310':null;const ps=agentData.proposals.filter(p=>!course||p.course===course);return heading(courseOnly?'Course insights · AIM310':'Improvement agent','Aggregate observations → proposals → human decisions → outcome measurement.')+`<p class="feedback">Collection runs only while this local page is open. External LMS signals require future integrations. Approval never automatically changes application behavior.</p><div class="agent-grid">${metrics.map(m=>{const t=totals(m,course);return `<section class="card"><h3>${m}</h3><strong>${t.count}</strong><p>${t.opportunities} observed opportunities</p></section>`}).join('')}</div><section class="card"><h2>Proposal review</h2>${agentButton('Gather proposals','gather')}${agentButton('Add labeled demonstration observations','sample')}<p>Demonstration observations are synthetic; no names or messages are collected.</p>${ps.map(p=>`<article class="proposal"><h3>${esc(p.metric)}</h3><p>${esc(p.status)} · ${esc(p.course)} · Priority ${p.weight}</p><p>${p.metric==='Unanswered agent questions'?'Draft a reviewed knowledge source for this knowledge gap.':'Investigate the affected process and document a human-led fix.'}</p>${p.status==='Proposed'?agentButton('Approve proposal','approve:'+p.id)+agentButton('Reject proposal','reject:'+p.id):''}${p.status==='Approved'?btn('Write approved knowledge','#knowledge',true)+agentButton('Mark human fix completed','fix:'+p.id):''}${p.status==='Measuring'?agentButton('Measure outcome','measure:'+p.id):''}${p.result?`<p>${esc(p.result)}</p>`:''}</article>`).join('')||'<p>No proposals yet. Gather after observations are available.</p>'}</section><details class="card"><summary>Audit and learning model</summary><p>Proposal priority uses approved and improved outcomes. Three rejected proposals suppress that metric. This is a transparent local feedback heuristic, not model training.</p><p>${agentData.logs.length} agent turns logged with timestamp, agent ID, fixed version, role, course, outcome, source IDs and redacted-question fingerprint.</p>${agentButton('Export agent audit and aggregate data','export')}</details>`;}
const beforeAgentsRender=render;
render=function(){const [route,id]=location.hash.slice(1).split('/');let body;if(route==='agents')body=agentHome();if(route==='agent-builder')body=builderPage(id);if(route==='agent')body=agentChat(id);if(route==='knowledge')body=knowledgePage();if(route==='improvement'||route==='course-insights')body=improvementPage(route==='course-insights');if(body!==undefined){document.getElementById('app').innerHTML=integratedShell(route,body,model.role);decorateRole(model.role);bind();document.title='Scholarion · Agent workspace';}else beforeAgentsRender();const nav=document.querySelector('.sidebar nav');if(nav&&!nav.querySelector('[data-agent-nav]'))nav.insertAdjacentHTML('beforeend',`<a class="nav-item" data-agent-nav href="#agents">${icon('spark')}<span>Agents</span></a>${canBuild()?`<a class="nav-item" href="#agent-builder">${icon('code')}<span>Agent Builder</span></a><a class="nav-item" href="#improvement">${icon('chart')}<span>Improvement agent</span></a>`:''}`);};
document.addEventListener('input',e=>{if(!builder)return;const t=e.target,d=builder.draft;if(t.name==='agent-role'){builder.draft=AC.defaults(t.value);render();}if(t.name==='agent-name')d.name=t.value;if(t.name==='agent-audience')d.audience=t.value;if(t.name==='agent-scope')d.scope=t.value;if(t.name==='agent-instructions')d.instructions=t.value;if(t.dataset.config)d[t.dataset.config]=[...document.querySelectorAll(`[data-config="${t.dataset.config}"]:checked`)].map(x=>x.value);});
function storeDraft(activate=false){const d=builder.draft;AC.validate(d,model.role);let a=agentData.agents.find(a=>a.id===builder.id);if(!a){a={id:crypto.randomUUID()};agentData.agents.push(a);builder.id=a.id;}if(a.draft&&!ownAgent(a))throw Error('Outside your assigned course.');a.draft=structuredClone(d);if(activate)a.active=AC.activate(d,model.role,a.active);saveAgents();builder=null;location.hash='agents';toast(activate?'Fixed version activated locally.':'Draft saved. Active version unchanged.');}
document.addEventListener('click',e=>{const action=e.target.closest('[data-agent]')?.dataset.agent;if(!action)return;try{if(action==='next'){step++;render();}if(action==='back'){step--;render();}if(action==='save'||action==='activate')storeDraft(action==='activate');if(!canBuild())return;if(action==='sample'){metrics.forEach(m=>signal(m,3,5));toast('Synthetic observations added for AIM310.');render();}if(action==='gather'){metrics.forEach(metric=>{const history=agentData.proposals.filter(p=>p.metric===metric);if(history.filter(p=>p.status==='Rejected').length>=3)return;const t=totals(metric,'AIM310');if(t.count&&!history.some(p=>['Proposed','Approved','Measuring'].includes(p.status)))agentData.proposals.push({id:crypto.randomUUID(),metric,course:'AIM310',status:'Proposed',baseline:t,weight:1+history.filter(p=>p.status==='Approved'||p.result==='Improved').length});});saveAgents();render();}const [verb,id]=action.split(':');const p=agentData.proposals.find(p=>p.id===id);if(p&&(model.role==='admin'||p.course==='AIM310')){if(verb==='approve'&&p.status==='Proposed')p.status='Approved';if(verb==='reject'&&p.status==='Proposed')p.status='Rejected';if(verb==='fix'&&p.status==='Approved'){p.status='Measuring';p.since=Date.now();p.baseline=totals(p.metric,p.course);}if(verb==='measure'&&p.status==='Measuring'){p.result=AC.measure(p.baseline,totals(p.metric,p.course,p.since));if(p.result!=='Insufficient observations')p.status='Evaluated';}saveAgents();render();}if(action==='export')download('scholarion-agent-audit.json',JSON.stringify({release:'2026.10.3-r103',logs:agentData.logs,signals:agentData.signals,proposals:agentData.proposals},null,2),'application/json');}catch(err){const out=document.getElementById('agent-error');if(out)out.textContent=err.message;else toast(err.message);}});
document.addEventListener('submit',async e=>{if(e.target.id==='knowledge-form'){e.preventDefault();if(!canBuild())return;const f=new FormData(e.target);agentData.knowledge.push({id:crypto.randomUUID(),pack:f.get('pack'),keywords:f.get('keywords').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean),answer:f.get('answer').trim(),course:model.role==='faculty'?'AIM310':null,approved:true});saveAgents();render();toast('Human-reviewed knowledge is now available to agents with this pack.');}if(e.target.id==='agent-chat'){e.preventDefault();const a=agentData.agents.find(a=>a.id===e.target.dataset.id);if(!a?.active)return;const q=AC.redact(new FormData(e.target).get('question'));e.target.reset();const result=AC.answer(q,a.active,agentData.knowledge,'AIM310');const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(q));agentData.logs.push({time:new Date().toISOString(),agent:a.id,version:a.active.version,role:model.role,course:'AIM310',outcome:result.outcome,sources:result.sources,fingerprint:Array.from(new Uint8Array(hash)).map(b=>b.toString(16).padStart(2,'0')).join('')});signal('Unanswered agent questions',result.outcome==='unverified'?1:0,1);saveAgents();const out=document.getElementById('agent-answer');if(out)out.innerHTML=result.sources.length?result.text.split(/(?<=[.!?])\s+/).map(s=>`<p>${esc(s)} <a href="#knowledge">[Source: ${esc(result.sources[0])}]</a></p>`).join(''):`<p>${esc(result.text)}</p>`;}});
render();
// Extend support with the same reviewed library and count completed empty searches.
const helpBeforeAgents=help;
help=function(){return helpBeforeAgents()+`<section class="card"><h2>Reviewed knowledge</h2>${agentData.knowledge.filter(k=>k.approved&&!k.course).map(k=>`<p>${esc(k.answer)} <a href="#knowledge">[${esc(k.id)}]</a></p>`).join('')}${btn('Ask Help Desk','#agent/seed-0',true)}</section>`;};
document.addEventListener('change',e=>{if(e.target.id==='search'&&e.target.value.trim()){const hits=document.querySelectorAll('#search-results a').length;signal('Empty help searches',hits?0:1,1);}});
document.addEventListener('click',e=>{if(e.target.closest('[data-support-topic]'))signal('Support requests',1,1);});
const agentHomeBeforeDrafts=agentHome;
agentHome=function(){return agentHomeBeforeDrafts()+(canBuild()?`<section class="card"><h2>Saved drafts</h2>${agentData.agents.filter(ownAgent).map(a=>`<p>${esc(a.draft.name)} · ${a.active?'Active v'+a.active.version+' remains unchanged until reactivation':'Not activated'} ${btn('Continue editing','#agent-builder/'+a.id,true)}</p>`).join('')}</section>`:'');};
render();


